  `cancelById` int NOT NULL,
  `cancelByType` varchar(5) NOT NULL,
  `cancelByUser` varchar(45) NOT NULL,
  `cancelDateTime` datetime DEFAULT NULL,
  `issuedById` int NOT NULL,
  `issuedByType` varchar(5) DEFAULT NULL,
  `issuedByUser` varchar(45) NOT NULL,
  `issuedDateTime` datetime DEFAULT NULL,
  `voidById` int NOT NULL,
  `voidByType` varchar(5) DEFAULT NULL,
  `voidByUser` varchar(45) NOT NULL,
  `voidDateTime` datetime DEFAULT NULL,
  `partyName` varchar(255) DEFAULT NULL,
