  `itineraryRef` varchar(20) NOT NULL,
  `paxType` varchar(5) NOT NULL,
  `refNumber` varchar(20) NOT NULL,
  `firstName` varchar(45) NOT NULL,
  `lastName` varchar(45) NOT NULL,
  `gender` varchar(5) NOT NULL,
  `docType` varchar(5) DEFAULT NULL,
  `countryOfIssue` varchar(5) DEFAULT NULL,
  `docNumber` varchar(25) DEFAULT NULL,
  `docNationality` varchar(5) DEFAULT NULL,
  `dateOfBirth` date DEFAULT NULL,
  `docExpDate` date DEFAULT NULL,
  `docIssueDate` date DEFAULT NULL,
  `rph` varchar(20) NOT NULL,
  `elementId` varchar(20) NOT NULL,
  `ticketRef` varchar(20) DEFAULT NULL,
  `ticketNumber` varchar(20) DEFAULT NULL,
  `ticketStatus` varchar(3) NOT NULL,
  `validatingCarrier` varchar(10) NOT NULL,
  `baseFare` float(20,2) DEFAULT '0.00',
  `eqBaseFare` float(20,2) DEFAULT '0.00',
  `taxes` float(20,2) DEFAULT '0.00',
  `eqTaxes` float(20,2) DEFAULT '0.00',
  `totalFare` float(20,2) DEFAULT '0.00',
  `eqTotalFare` float(20,2) DEFAULT '0.00',
  `currencyCode` varchar(5) DEFAULT NULL,
  `eqCurrencyCode` varchar(5) DEFAULT NULL,
  `rcCurrencyCode` varchar(5) NOT NULL,
  `currencyRate` float(20,2) DEFAULT NULL,
  `eqCurrencyRate` float(20,2) DEFAULT NULL,
  `rcCurrencyRate` float(20,2) NOT NULL,
  `commission` float(20,2) DEFAULT '0.00',
  `taxBreakdowns` varchar(1000) NOT NULL,
  `eqTaxBreakdowns` varchar(1000) NOT NULL,
  `messages` varchar(1000) DEFAULT NULL,
  `segment` varchar(25) DEFAULT NULL,
  `baggage` varchar(25) DEFAULT NULL,
  `fareType` varchar(25) DEFAULT NULL,
  `pnrType` varchar(20) DEFAULT NULL,
  `b2c` float(20,2) DEFAULT '0.00',
  `eqB2c` float(20,2) DEFAULT '0.00',
  `b2b` float(20,2) DEFAULT '0.00',
  `eqB2b` float(20,2) DEFAULT '0.00',
  `b2b2c` float(20,2) DEFAULT '0.00',
  `eqB2b2c` float(20,2) DEFAULT '0.00',
  `b2b2b` float(20,2) DEFAULT '0.00',
  `eqB2b2b` float(20,2) DEFAULT '0.00',
  `b2b2b2c` float(20,2) DEFAULT '0.00',
  `eqB2b2b2c` float(20,2) DEFAULT '0.00',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=27 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
