DROP TABLE IF EXISTS `flight_itineraryref_markup_infos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `flight_itineraryref_markup_infos` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `agentId` bigint unsigned NOT NULL,
  `parentId` bigint unsigned NOT NULL DEFAULT '0',
  `userId` bigint unsigned NOT NULL DEFAULT '0',
  `itineraryRef` varchar(20) NOT NULL,
  `title` varchar(45) NOT NULL DEFAULT 'BSC',
  `itineraryType` enum('INT','DOM') NOT NULL DEFAULT 'DOM',
  `fareType` enum('BF','TF') NOT NULL DEFAULT 'BF',
  `serviceFeeType` enum('FIX','PCT') NOT NULL DEFAULT 'FIX',
  `passengerType` enum('ALL','ADT','CNN','INF','PLM') NOT NULL DEFAULT 'ALL',
  `serviceType` enum('lsm','tbp','cm','ncm','md','sector-wise') NOT NULL DEFAULT 'lsm',
  `markupType` enum('b2c','b2b','b2b2c','b2b2b','b2b2b2c') NOT NULL DEFAULT 'b2c',
  `serviceFee` double(10,2) NOT NULL,
  `airlineType` enum('Sabre','Pia','Airblue','Emirate','Oman','Airsial','Jazeeraairways') DEFAULT 'Sabre',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=36 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
