DROP TABLE IF EXISTS `permissions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `permissions` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `title` varchar(255) NOT NULL,
  `moduleType` varchar(255) NOT NULL,
  `agentId` int NOT NULL,
  `parentId` int NOT NULL,
  `userId` int NOT NULL,
  `permissionTypeId` bigint unsigned NOT NULL,
  `assignType` enum('user','agent') NOT NULL,
  `postbyId` int NOT NULL,
  `postbyType` enum('user','agent','owner') NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `permissions_permission_id_foreign` (`permissionTypeId`),
  CONSTRAINT `permissions_permission_id_foreign` FOREIGN KEY (`permissionTypeId`) REFERENCES `permission_types` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1854 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
