DROP TABLE IF EXISTS `tour_packages`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tour_packages` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `cms_cp_id` int NOT NULL,
  `domestic_states_id` bigint DEFAULT NULL COMMENT 'kpk,punjab etc',
  `meta_keyword` varchar(255) DEFAULT NULL,
  `tour_days` int DEFAULT NULL,
  `tour_availability` date DEFAULT NULL COMMENT 'tour starting date',
  `price_label` enum('0','1') DEFAULT '0' COMMENT '0=couple, 1=per person',
  `discount_price` decimal(10,2) DEFAULT NULL,
  `departure_location` varchar(50) DEFAULT NULL,
  `destination_location` varchar(50) DEFAULT NULL,
  `tour_services` text,
  `map` text,
  `days_details` text,
  `show_departure` enum('0','1') DEFAULT '0' COMMENT '0=hidden, 1=show',
  `fixed_date` varchar(10) DEFAULT NULL,
  `tour_status` enum('0','1') NOT NULL DEFAULT '0',
  `created_by` bigint NOT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_by` bigint NOT NULL,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `cmscpId` (`cms_cp_id`),
  CONSTRAINT `cmscpId` FOREIGN KEY (`cms_cp_id`) REFERENCES `content_pages` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=48 DEFAULT CHARSET=latin1;
