DROP TABLE IF EXISTS `umrah_booking_customers`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `umrah_booking_customers` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `customerId` bigint NOT NULL,
  `umrahVisaPrice` double(8,2) NOT NULL,
  `umrahSectorId` bigint unsigned NOT NULL,
  `umrahVehicleId` bigint unsigned NOT NULL,
  `umrahVehiclePrice` double(8,2) NOT NULL,
  `nationality` enum('0','1') NOT NULL COMMENT '0=Pakistan, 1=Others',
  `transport` enum('0','1') NOT NULL COMMENT '0=No Transport, 1=Have Transport',
  `city` int NOT NULL,
  `adultsCount` int NOT NULL,
  `childrenCount` int NOT NULL,
  `infantsCount` int NOT NULL,
  `totalRoom` int NOT NULL,
  `totalNight` int NOT NULL,
  `totalPrice` double(8,2) NOT NULL,
  `created_by` bigint NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `umrah_vehicle_Id` (`umrahVehicleId`),
  KEY `umrah_sector_Id` (`umrahSectorId`),
  KEY `umrah_booking_customerid_foreign` (`customerId`),
  CONSTRAINT `umrah_booking_customerid_foreign` FOREIGN KEY (`customerId`) REFERENCES `customers` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `umrah_sector_Id` FOREIGN KEY (`umrahSectorId`) REFERENCES `umrah_transport_sectors` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `umrah_vehicle_Id` FOREIGN KEY (`umrahVehicleId`) REFERENCES `umrah_vehicles` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=394 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

